fn solve(input: Vec<i8>) -> Vec<&'static str> {
    // Helper to test if n is a power of two (n > 0 and only one 1-bit).
    fn is_power_of_two(n: i32) -> bool {
        n > 0 && (n & (n - 1)) == 0
    }

    // Implements the "limited-prime" test as specified:
    // p ≤ 1     -> not prime
    // p = 2     -> prime
    // p > 2 even-> not prime
    // p > 2 odd -> prime
    fn limited_prime(p: i32) -> bool {
        if p <= 1 {
            false
        } else if p == 2 {
            true
        } else {
            p % 2 != 0
        }
    }

    // Read number of test cases
    let t = input[0] as usize;
    let mut result = Vec::with_capacity(t);

    for i in 0..t {
        let n = input[i + 1] as i32;
        let winner = if n == 1 {
            "FastestFinger"
        } else if n == 2 {
            "Ashishgup"
        } else if is_power_of_two(n) {
            "FastestFinger"
        } else if n % 4 != 2 {
            "Ashishgup"
        } else {
            // n % 4 == 2 here
            let p = n / 2;
            if limited_prime(p) {
                "FastestFinger"
            } else {
                "Ashishgup"
            }
        };
        result.push(winner);
    }

    result
}